ndpoint, upstream_endpoint, node, stream, request_type, billing_type, countStateIf(calls = 1) AS calls, countState() AS financial_records, sumState(web_search_quantity) AS web_search_quantity, countIfState(web_search_observed = 1) AS web_search_observed, countIfState(web_search_fee_observed = 1) AS web_search_fee_observed, sumState(web_search_amount) AS web_search_amount, sumState(web_search_original) AS web_search_original, sumState(web_search_discount) AS web_search_discount, sumState(web_fetch_quantity) AS web_fetch_quantity, countIfState(web_fetch_observed = 1) AS web_fetch_observed, countIfState(web_fetch_fee_observed = 1) AS web_fetch_fee_observed, sumState(web_fetch_amount) AS web_fetch_amount, sumState(web_fetch_original) AS web_fetch_original, sumState(web_fetch_discount) AS web_fetch_discount, sumState(code_execution_quantity) AS code_execution_quantity, countIfState(code_execution_observed = 1) AS code_execution_observed, countIfState(code_execution_fee_observed = 1) AS code_execution_fee_observed, sumState(code_execution_amount) AS code_execution_amount, sumState(code_execution_original) AS code_execution_original, sumState(code_execution_discount) AS code_execution_discount FROM (WITH JSONExtractArrayRaw(ratio_snapshot, 'server_tool_fees') AS fees, (log_type IN (2, 5)) AND isValidJSON(server_tool_usage) AND (JSONType(server_tool_usage) = 'Object') AND (JSONExtractString(server_tool_usage, 'provider') = 'anthropic') AND (match(JSONExtractRaw(server_tool_usage, 'web_search_requests'), '^(0|[1-9][0-9]*)$') AND (toInt128OrNull(JSONExtractRaw(server_tool_usage, 'web_search_requests')) IS NOT NULL) AND (toInt128OrZero(JSONExtractRaw(server_tool_usage, 'web_search_requests')) <= 2147483647)) AS web_search_quantity_valid, arrayFilter(f -> (JSONExtractString(f, 'tool') = 'web_search'), fees) AS web_search_fees, web_search_fees[1] AS web_search_fee, JSONExtractRaw(web_search_fee, 'amount_micro') AS web_search_amount_raw, JSONExtractRaw(web_search_fee, 'original_a