b_fetch_fee, 'list_price_micro'), '^(0|[1-9][0-9]*)$') AND (toInt128OrNull(JSONExtractRaw(web_fetch_fee, 'list_price_micro')) IS NOT NULL) AND (toInt128OrZero(JSONExtractRaw(web_fetch_fee, 'list_price_micro')) <= 9223372036854775807)) AND ((match(JSONExtractRaw(web_fetch_fee, 'quantity'), '^(0|[1-9][0-9]*)$') AND (toInt128OrNull(JSONExtractRaw(web_fetch_fee, 'quantity')) IS NOT NULL) AND (toInt128OrZero(JSONExtractRaw(web_fetch_fee, 'quantity')) <= 2147483647)) OR ((toInt128OrZero(JSONExtractRaw(web_fetch_fee, 'pricing', 'price_per_request_micro')) = 0) AND (JSONExtractRaw(web_fetch_fee, 'quantity') = 'null'))) AND (toInt128OrZero(JSONExtractRaw(web_fetch_fee, 'list_price_micro')) = (toInt128OrZero(JSONExtractRaw(web_fetch_fee, 'pricing', 'price_per_request_micro')) * toInt128OrZero(JSONExtractRaw(web_fetch_fee, 'quantity')))))))) AS web_fetch_fee_valid, (log_type IN (2, 5)) AND isValidJSON(server_tool_usage) AND (JSONType(server_tool_usage) = 'Object') AND (JSONExtractString(server_tool_usage, 'provider') = 'anthropic') AND (match(JSONExtractRaw(server_tool_usage, 'code_execution_requests'), '^(0|[1-9][0-9]*)$') AND (toInt128OrNull(JSONExtractRaw(server_tool_usage, 'code_execution_requests')) IS NOT NULL) AND (toInt128OrZero(JSONExtractRaw(server_tool_usage, 'code_execution_requests')) <= 2147483647)) AS code_execution_quantity_valid SELECT toStartOfMinute(ts) AS minute, user_id, api_key_id, group_code, model, channel_id, requested_model, upstream_model, endpoint, upstream_endpoint, node, stream, request_type, billing_type, toUInt64(log_type IN (2, 5)) AS calls, toUInt64(1) AS financial_records, if(web_search_quantity_valid, toInt128OrZero(JSONExtractRaw(server_tool_usage, 'web_search_requests')), toInt128(0)) AS web_search_quantity, toUInt64(web_search_quantity_valid) AS web_search_observed, toUInt64(web_search_fee_valid) AS web_search_fee_observed, if(web_search_fee_valid, if(log_type = 6, -toInt128OrZero(web_search_amount_raw), toInt128OrZero(web_search_amount_r